mapper.select:
select , 1 - (v.vector <=> cast(#{vector} as vector)) as vector_score
from ${table} v
join ai_knowledge_chunk c on c.id = v.chunk_id and c.knowledge_base_id = v.knowledge_base_id
join ai_knowledge_document d on d.id = c.document_id and d.knowledge_base_id = c.knowledge_base_id
join ai_knowledge_base b on b.id = d.knowledge_base_id
where 
  and v.index_version = #{base.activeIndexVersion}
  and v.model_connection_id = #{base.activeConnectionId}
  and v.processing_version = d.processing_version

  and 1 - (v.vector <=> cast(#{vector} as vector)) >= #{base.similarityThreshold}

order by v.vector <=> cast(#{vector} as vector), c.id
limit #{base.vectorRecallSize}

select count(*) from ${table}
where knowledge_base_id = #{base.id} and index_version = #{base.buildingIndexVersion}
  and chunk_id = #{chunk.chunkId} and processing_version = #{chunk.processingVersion}
  and model_connection_id = #{base.embeddingConnectionId}
